// Confere o formulário do prestador e lê os pacotes POR REGRA (preço não pode sair errado nem ser inventado pela IA).
let b = $('🔔 Pedido de criação (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 30);
const num = s => Number(String(s ?? '').replace(/[^\d,.]/g, '').replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')) || 0;
const opcao = (v, lista, padrao) => lista.includes(Number(v)) ? Number(v) : padrao;
const fone = v => { let f = String(v || '').replace(/\D/g, '').slice(0, 13); return f.length >= 10 && f.length <= 11 ? '55' + f : f; };
const crypto = require('crypto');
const erros = [];

// "Essencial - R$ 1.500 - site de 1 página; formulário de contato" → { nome, preco, itens }
const pacotes = String(b.pacotes || '').split('\n').map(l => l.trim()).filter(Boolean).slice(0, 3).map((l, i) => {
  const pr = l.match(/R\$\s*([\d.]+(?:,\d{1,2})?)/i);
  if (!pr) return null;
  const antes = l.slice(0, pr.index).replace(/[\s\-–—|:]+$/, '').trim(), depois = l.slice(pr.index + pr[0].length).replace(/^[\s\-–—|:]+/, '').trim();
  return { k: 'k' + (i + 1), nome: limpa(antes, 40) || 'Pacote ' + (i + 1), preco: Math.round(num(pr[1]) * 100) / 100,
    itens: depois.split(/;|•/).map(x => limpa(x, 120)).filter(Boolean).slice(0, 10) };
}).filter(p => p && p.preco > 0);
if (!pacotes.length && num(b.valor) > 0) pacotes.push({ k: 'k1', nome: 'Proposta', preco: Math.round(num(b.valor) * 100) / 100, itens: [] });

const dados = {
  prestador: { nome: limpa(b.prestador_nome, 60), empresa: limpa(b.prestador_empresa, 60), whatsapp: fone(b.prestador_whatsapp), email: limpa(b.prestador_email, 80),
    pix: limpa(b.pix, 77), cidade: limpa(b.cidade, 40), cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : '' },
  cliente: { nome: limpa(b.cliente_nome, 60), empresa: limpa(b.cliente_empresa, 60), whatsapp: fone(b.cliente_whatsapp) },
  briefing: limpa(b.briefing, 2500), entregas: limpa(b.entregas, 2000), pacotes,
  prazo_dias: Math.min(365, Math.max(0, Math.round(num(b.prazo_dias)))), sinal_pct: Math.min(100, Math.max(0, Math.round(num(b.sinal_pct ?? 50)))),
  validade_dias: opcao(b.validade_dias, [7, 15, 30, 60], 15), garantia: limpa(b.garantia, 300), pagamento: limpa(b.pagamento, 300),
};
if (dados.prestador.nome.length < 2) erros.push('Digite o seu nome (prestador).');
if (dados.cliente.nome.length < 2) erros.push('Digite o nome do cliente.');
if (dados.briefing.length < 20) erros.push('Conte o que o cliente precisa (pelo menos uma frase).');
if (!pacotes.length) erros.push('Informe o valor ou os pacotes com preço (ex.: Essencial - R$ 1.500 - itens).');
if (dados.prestador.email && !/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(dados.prestador.email)) erros.push('O e-mail do prestador parece errado.');

const chaveP = /^[a-f0-9]{16}$/.test(String(b.prestador || '')) ? String(b.prestador) : crypto.randomBytes(8).toString('hex');
const id = (slug(dados.cliente.empresa || dados.cliente.nome) || 'proposta') + '-' + crypto.randomBytes(2).toString('hex');
const base = String($('🔔 Pedido de criação (POST)').first().json.webhookUrl || '').split('/webhook/')[0] + '/webhook';
const brl = n => 'R$ ' + n.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const resumo_ia = JSON.stringify({ prestador: dados.prestador.empresa || dados.prestador.nome, cliente: dados.cliente.empresa || dados.cliente.nome,
  o_que_o_cliente_precisa: dados.briefing, entregas_combinadas: dados.entregas || '(não detalhadas)',
  pacotes: pacotes.map(p => ({ k: p.k, nome: p.nome, preco: brl(p.preco), itens: p.itens })), prazo_total: dados.prazo_dias ? dados.prazo_dias + ' dias' : '(não informado)',
  sinal: dados.sinal_pct + '%', garantia: dados.garantia || '(nenhuma)', forma_de_pagamento: dados.pagamento || '(não informada)' }, null, 1);
return [{ json: { valido: erros.length === 0, erros, id, chaveP, dados, resumo_ia, chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13),
  link: `${base}/proposta/${id}/ver`, painel_url: `${base}/proposta/${chaveP}/painel`, k_prestador: 'ppp:' + chaveP } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Lê a proposta escrita pela redatora e prepara o pedido da revisora (ela confere tudo contra os dados do prestador).
const v = $('🧩 Confere o pedido').first().json;
let r = null;
try { r = parseJSON($('🤖 Redatora da proposta').first().json.output); } catch (e) {}
return [{ json: { escreveu: !!r, texto_revisora: 'DADOS DO PRESTADOR (a única fonte de verdade):\n' + v.resumo_ia
  + '\n\nPROPOSTA DA REDATORA:\n' + (r ? JSON.stringify(r, null, 1) : '(a redatora não respondeu: escreva todos os campos você mesma, seguindo as regras)') } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Junta os dados do prestador com o texto revisado. Preço, prazo, sinal e garantia vêm SEMPRE do prestador; a IA só escreve.
const v = $('🧩 Confere o pedido').first().json, d = v.dados;
const crypto = require('crypto');
let red = null, rev = null, prest = null;
try { red = parseJSON($('🤖 Redatora da proposta').first().json.output); } catch (e) {}
try { rev = parseJSON($('🤖 Revisora da proposta').first().json.output); } catch (e) {}
try { prest = JSON.parse($('📖 Lê o prestador').first().json.prestador || 'null'); } catch (e) {}
red = red || {}; rev = rev || {};
const txt = (x, max) => String(x ?? '').replace(/[<>]/g, '').trim().slice(0, max);
const campo = k => (rev[k] !== undefined && rev[k] !== '' && rev[k] !== null && !(Array.isArray(rev[k]) && !rev[k].length)) ? rev[k] : red[k];
const lista = (k, max, n) => Array.isArray(campo(k)) ? campo(k).map(x => txt(x, max)).filter(Boolean).slice(0, n) : [];
const agora = Date.now();

// o prestador tem as chaves dos avisos no celular dele (criadas na 1ª proposta)
if (!prest || !prest.vapid) {
  const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
  const jwk = privateKey.export({ format: 'jwk' }), pub = publicKey.export({ format: 'jwk' });
  const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
  prest = { chaveP: v.chaveP, criado: agora, vapid: { publica: b64u(Buffer.concat([Buffer.from([4]), unb(pub.x), unb(pub.y)])), privada: { kty: 'EC', crv: 'P-256', d: jwk.d, x: jwk.x, y: jwk.y } } };
}
Object.assign(prest, { nome: d.prestador.nome, empresa: d.prestador.empresa, whatsapp: d.prestador.whatsapp, email: d.prestador.email });

const iaPac = Array.isArray(campo('pacotes')) ? campo('pacotes') : [];
const pacotes = d.pacotes.map(p => {
  const x = iaPac.find(y => y && y.k === p.k) || {};
  return { ...p, descricao: txt(x.descricao, 240), destaques: (Array.isArray(x.destaques) ? x.destaques : []).map(y => txt(y, 80)).filter(Boolean).slice(0, 4) };
});
const escopo = lista('escopo', 160, 12);
const textos = {
  titulo: txt(campo('titulo'), 90) || `Proposta para ${d.cliente.empresa || d.cliente.nome}`,
  diagnostico: txt(campo('diagnostico'), 700) || d.briefing.slice(0, 700),
  objetivo: txt(campo('objetivo'), 300),
  solucao: txt(campo('solucao'), 900),
  escopo: escopo.length ? escopo : d.entregas.split(/\n|;/).map(x => txt(x, 160)).filter(Boolean).slice(0, 12),
  cronograma: (Array.isArray(campo('cronograma')) ? campo('cronograma') : []).map(x => ({ etapa: txt(x && x.etapa, 120), prazo: txt(x && x.prazo, 40) })).filter(x => x.etapa).slice(0, 8),
  // sem garantia escrita pelo prestador, a proposta não promete garantia nenhuma
  garantias: d.garantia ? (lista('garantias', 160, 4).length ? lista('garantias', 160, 4) : [d.garantia]) : [],
  faq: (Array.isArray(campo('faq')) ? campo('faq') : []).map(x => ({ p: txt(x && x.p, 140), r: txt(x && x.r, 400) })).filter(x => x.p && x.r).slice(0, 5),
  proximos_passos: lista('proximos_passos', 160, 5).length ? lista('proximos_passos', 160, 5) : ['Escolha o pacote e toque em "Aceitar a proposta"', d.sinal_pct ? 'Pague o sinal pelo Pix' : 'Combine o pagamento', 'Começamos o trabalho'],
  mensagem_whatsapp: txt(campo('mensagem_whatsapp'), 400),
};
const recomendado = d.pacotes.some(p => p.k === campo('recomendado')) ? campo('recomendado') : (d.pacotes[1] || d.pacotes[0]).k;
const proposta = { id: v.id, chaveP: v.chaveP, criado: agora, validade_ate: agora + d.validade_dias * 86400000, prestador: d.prestador, cliente: d.cliente,
  briefing: d.briefing, pacotes, recomendado, sinal_pct: d.sinal_pct, prazo_dias: d.prazo_dias, pagamento: d.pagamento, garantia: d.garantia, textos,
  feito_com_ia: !!red.titulo, revisado: !!(rev.titulo || rev.problemas), problemas_revisao: Array.isArray(rev.problemas) ? rev.problemas.map(p => txt(p, 200)).slice(0, 10) : [] };
const precos = pacotes.map(p => p.preco);
return [{ json: { id: v.id, chaveP: v.chaveP, proposta: JSON.stringify(proposta), prestador: JSON.stringify(prest),
  indice: JSON.stringify({ id: v.id, titulo: textos.titulo, cliente: d.cliente.empresa || d.cliente.nome, de: Math.min(...precos), ate: Math.max(...precos), criado: agora }) } }];

// Pix copia e cola no padrão BR Code do Banco Central (EMV + CRC16), o mesmo do agente de vendas.
function ppPix(chave, nome, cidade, valor, txid) {
  const emv = (id, v) => { const s = String(v); return id + String(s.length).padStart(2, '0') + s; };
  const ascii = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 ]/g, '').toUpperCase();
  let p = emv('00', '01') + emv('26', emv('00', 'br.gov.bcb.pix') + emv('01', chave)) + emv('52', '0000') + emv('53', '986') + emv('54', valor.toFixed(2));
  p += emv('58', 'BR') + emv('59', ascii(nome).slice(0, 25) || 'RECEBEDOR') + emv('60', ascii(cidade).slice(0, 15) || 'BRASIL')
    + emv('62', emv('05', String(txid).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || '***')) + '6304';
  let c = 0xFFFF;
  for (let i = 0; i < p.length; i++) { c ^= p.charCodeAt(i) << 8; for (let j = 0; j < 8; j++) { c = (c & 0x8000) ? ((c << 1) ^ 0x1021) : (c << 1); c &= 0xFFFF; } }
  return p + c.toString(16).toUpperCase().padStart(4, '0');
}
const ppBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// Página da proposta para o cliente. "?p=1" = prévia do prestador e robôs de pré-visualização (WhatsApp etc.) não contam como visita.
const ent = $('🔔 Abrir proposta (GET)').first().json;
const q = ent.query || {}, ua = String((ent.headers || {})['user-agent'] || '');
let pr = null, ac = null, pg = null;
try { pr = JSON.parse($('📖 Lê a proposta').first().json.proposta || 'null'); } catch (e) {}
try { ac = JSON.parse($('📖 Lê o aceite').first().json.aceite || 'null'); } catch (e) {}
try { pg = JSON.parse($('📖 Lê o pagamento').first().json.pagamento || 'null'); } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
if (!pr) return [{ json: { contar: false, codigo: 404, html: `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proposta não encontrada</title><meta name="robots" content="noindex"></head>
<body style="font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#f6f6f4;color:#222;text-align:center;padding:24px"><div><div style="font-size:56px">📄</div><h1 style="font-size:22px">Proposta não encontrada</h1><p style="color:#666">O link pode estar incompleto ou a proposta já foi removida.</p></div></body></html>` } }];
const agora = Date.now();
const vencida = !ac && agora > pr.validade_ate;
const robo = /bot|crawl|spider|preview|facebookexternalhit|whatsapp|telegram|slack|discord|curl|python/i.test(ua);
const C = pr.prestador.cor || '#0f766e';
const lum = c => { const v = [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16) / 255).map(x => x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4)); return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2]; };
const corTexto = lum(C) > 0.45 ? '#111111' : '#ffffff';
const data = ms => new Date(ms).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const dataCurta = ms => new Date(ms).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const escolhido = ac ? pr.pacotes.find(p => p.k === ac.pacote) : null;
let pix = null;
if (ac && escolhido && pr.sinal_pct > 0 && pr.prestador.pix) {
  const valor = Math.round(escolhido.preco * pr.sinal_pct) / 100;
  pix = { valor, texto: ppPix(pr.prestador.pix, pr.prestador.empresa || pr.prestador.nome, pr.prestador.cidade, valor, 'P' + pr.id.replace(/[^a-z0-9]/gi, '').slice(-20)) };
}
const T = pr.textos, quem = pr.prestador.empresa || pr.prestador.nome;
const wa = pr.prestador.whatsapp ? `https://wa.me/${pr.prestador.whatsapp}?text=${encodeURIComponent('Olá! Vi a proposta "' + T.titulo + '" e tenho uma dúvida.')}` : '';

function cliente(P) {
  var el = function (s) { return document.querySelector(s); };
  function toast(t) { var x = el('#toast'); x.textContent = t; x.classList.add('on'); clearTimeout(x._t); x._t = setTimeout(function () { x.classList.remove('on'); }, 4500); }
  function api(d) {
    return fetch('/webhook/proposta-api', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(Object.assign({ id: P.id }, d)) })
      .then(function (r) { return r.json(); }).catch(function () { return { ok: false, erro: 'Sem conexão. Tente de novo.' }; });
  }
  var escolha = P.recomendado;
  function marca() {
    document.querySelectorAll('[data-pac]').forEach(function (c) { c.classList.toggle('on', c.dataset.pac === escolha); });
    var p = P.pacotes.filter(function (x) { return x.k === escolha; })[0];
    if (el('#escolha')) el('#escolha').textContent = p.nome + ' · ' + p.preco_txt;
  }
  document.addEventListener('click', function (e) {
    var c = e.target.closest('[data-pac]'); if (c && !P.aceita) { escolha = c.dataset.pac; marca(); }
    var b = e.target.closest('[data-copiar]'); if (b) navigator.clipboard.writeText(el(b.dataset.copiar).textContent).then(function () { b.textContent = '✅ Copiado'; });
  });
  if (!P.aceita) marca();
  var f = el('#form-aceite');
  if (f) f.addEventListener('submit', function (e) {
    e.preventDefault();
    var bt = el('#bt-aceitar'); bt.disabled = true; bt.textContent = '⏳ Registrando…';
    api({ acao: 'aceitar', pacote: escolha, nome: el('#a-nome').value, documento: el('#a-doc').value, email: el('#a-email').value, aceite: el('#a-ok').checked }).then(function (r) {
      if (!r.ok) { bt.disabled = false; bt.textContent = '✅ Aceitar a proposta'; el('#erro').textContent = r.erro; return; }
      toast('Proposta aceita! 🎉'); setTimeout(function () { location.reload(); }, 900);
    });
  });
  var pg = el('#bt-paguei');
  if (pg) pg.addEventListener('click', function () {
    pg.disabled = true;
    api({ acao: 'paguei' }).then(function (r) { if (!r.ok) { pg.disabled = false; toast(r.erro); return; } toast('Obrigado! O prestador vai conferir e confirmar.'); setTimeout(function () { location.reload(); }, 900); });
  });
  if (P.pix && window.qrcode) { var q = qrcode(0, 'M'); q.addData(P.pix); q.make(); el('#qr-pix').innerHTML = q.createSvgTag({ cellSize: 5, margin: 2, scalable: true }); }
  el('#imprimir').addEventListener('click', function () { window.print(); });
}

const pacotesHtml = pr.pacotes.map(p => `<div class="pac${p.k === pr.recomendado ? ' rec' : ''}${ac && ac.pacote === p.k ? ' on' : ''}" data-pac="${p.k}" ${ac ? '' : 'role="button" tabindex="0"'}>
  ${p.k === pr.recomendado ? '<span class="selo">⭐ Recomendado</span>' : ''}<h3>${esc(p.nome)}</h3><div class="preco">${ppBRL(p.preco)}</div>
  ${p.descricao ? `<p class="sub">${esc(p.descricao)}</p>` : ''}${p.itens.length ? `<ul>${p.itens.map(i => `<li>✔️ ${esc(i)}</li>`).join('')}</ul>` : ''}
  ${p.destaques.length ? `<p class="dest">${p.destaques.map(esc).join(' · ')}</p>` : ''}</div>`).join('');
const aceiteHtml = ac ? `<section class="card ok"><h2>✅ Proposta aceita</h2><p>Pacote <b>${esc(escolhido ? escolhido.nome : ac.pacote)}</b> (${ppBRL(ac.valor)}) aceito por <b>${esc(ac.nome)}</b> em ${data(ac.quando)}.</p>
  ${pix ? `<div class="pix"><div id="qr-pix" aria-label="QR Code do Pix"></div><div><p><b>Sinal de ${pr.sinal_pct}%: ${ppBRL(pix.valor)}</b> no Pix</p><p class="sub">Abra o app do banco ➜ Pix ➜ ler QR Code ou "copia e cola".</p>
    <pre id="pix-txt">${esc(pix.texto)}</pre><div class="bts"><button class="bt" data-copiar="#pix-txt">📋 Copiar o Pix</button>
    ${pg ? '' : '<button class="bt pri" id="bt-paguei">💸 Já paguei o sinal</button>'}</div></div></div>`
    : `<p class="sub">${pr.sinal_pct > 0 ? 'O prestador vai combinar com você como pagar o sinal.' : 'O prestador vai combinar o pagamento com você.'}</p>`}
  ${pg ? `<p class="pago">${pg.status === 'confirmado' ? `💰 Pagamento confirmado pelo prestador em ${data(pg.confirmado)}.` : `🕒 Você informou o pagamento em ${data(pg.quando)}. O prestador vai conferir.`}</p>` : ''}</section>`
  : vencida ? `<section class="card"><h2>⌛ Esta proposta venceu em ${dataCurta(pr.validade_ate)}</h2><p class="sub">Fale com ${esc(quem)} para receber uma proposta atualizada.</p></section>`
  : `<form class="card" id="form-aceite"><h2>✍️ Aceitar a proposta</h2><p>Pacote escolhido: <b id="escolha"></b> <span class="sub">(toque em outro pacote acima para trocar)</span></p>
    <label for="a-nome">Nome completo</label><input id="a-nome" required maxlength="80" autocomplete="name">
    <div class="duas"><div><label for="a-doc">CPF ou CNPJ <small>(opcional)</small></label><input id="a-doc" maxlength="20" inputmode="numeric"></div>
    <div><label for="a-email">E-mail <small>(opcional)</small></label><input id="a-email" type="email" maxlength="80" autocomplete="email"></div></div>
    <label class="check"><input type="checkbox" id="a-ok" required> Li a proposta e aceito o pacote escolhido, o prazo e as condições de pagamento.</label>
    <p class="erro" id="erro" role="alert"></p><button class="bt pri cheio" id="bt-aceitar">✅ Aceitar a proposta</button>
    <p class="leg">Aceite eletrônico simples: registramos nome, data, hora, IP e navegador. Não é assinatura com certificado digital.</p></form>`;

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(T.titulo)} · ${esc(quem)}</title><meta name="robots" content="noindex"><meta property="og:title" content="${esc(T.titulo)}"><meta property="og:description" content="Proposta de ${esc(quem)} para ${esc(pr.cliente.empresa || pr.cliente.nome)}">
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js"></script>
<style>
:root{color-scheme:light;--marca:${C};--marcat:${corTexto};--tx:#18181b;--tx2:#52525b;--mu:#71717a;--fundo:#f6f6f4;--card:#fff;--borda:rgba(0,0,0,.1);--cod:#efeee9;--ok:#15803d;--er:#b42318}
@media (prefers-color-scheme:dark){:root{color-scheme:dark;--tx:#f4f4f5;--tx2:#c4c4cc;--mu:#a1a1aa;--fundo:#0e0e0f;--card:#1b1b1d;--borda:rgba(255,255,255,.12);--cod:#26262a;--ok:#4ade80;--er:#ff8a80}}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:var(--fundo);color:var(--tx);line-height:1.55}
header{background:var(--marca);color:var(--marcat);padding:28px 18px 30px}header .w{max-width:880px;margin:0 auto}
header small{opacity:.85;font-weight:600;letter-spacing:.04em;text-transform:uppercase;font-size:12.5px}header h1{font-size:clamp(24px,4vw,34px);line-height:1.15;margin:6px 0}header p{opacity:.92}
main{max-width:880px;margin:0 auto;padding:16px}
.card{background:var(--card);border:1px solid var(--borda);border-radius:18px;padding:20px;margin-top:14px}.card h2{font-size:18px;margin-bottom:8px}
.card.ok{border-color:var(--ok)}.sub{color:var(--tx2);font-size:14.5px}
ul.lista{list-style:none;display:grid;gap:6px}ul.lista li{padding-left:2px}
.crono{list-style:none;display:grid;gap:0}.crono li{display:grid;grid-template-columns:120px 1fr;gap:12px;padding:10px 0;border-bottom:1px solid var(--borda)}.crono b{color:var(--tx2);font-size:14px}
.pacs{display:grid;grid-template-columns:repeat(${Math.min(3, pr.pacotes.length)},minmax(0,1fr));gap:12px;margin-top:6px}
.pac{position:relative;border:1px solid var(--borda);border-radius:16px;padding:18px 16px;background:var(--fundo);cursor:pointer}
.pac.rec{border-color:var(--marca)}.pac.on{box-shadow:0 0 0 3px var(--marca) inset}
.pac h3{font-size:17px}.pac .preco{font-size:26px;font-weight:800;margin:4px 0 6px;font-variant-numeric:tabular-nums}.pac ul{list-style:none;display:grid;gap:4px;margin-top:8px;font-size:14px}
.selo{position:absolute;top:-11px;left:14px;background:var(--marca);color:var(--marcat);font-size:12px;font-weight:800;padding:2px 10px;border-radius:99px}
.dest{color:var(--tx2);font-size:13px;margin-top:8px}
label{display:block;font-weight:600;font-size:14px;margin-top:12px}label small{font-weight:400;color:var(--mu)}
input[type=text],input:not([type]),input[type=email]{width:100%;margin-top:6px;font:inherit;font-size:16px;padding:11px 13px;border-radius:12px;border:1px solid var(--borda);background:var(--fundo);color:var(--tx)}
.duas{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}
.check{display:flex;gap:10px;font-weight:500;margin-top:14px}.check input{margin-top:5px;width:18px;height:18px;flex:none}
.bts{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
.bt{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--borda);background:var(--card);color:var(--tx);font:inherit;font-weight:700;font-size:15px;padding:11px 16px;border-radius:12px;cursor:pointer;text-decoration:none}
.bt.pri{background:var(--marca);color:var(--marcat);border-color:transparent}.bt.cheio{width:100%;margin-top:14px;padding:14px}.bt[disabled]{opacity:.6}
.erro{color:var(--er);font-weight:600;margin-top:8px}.leg{color:var(--mu);font-size:12.5px;margin-top:10px}
.pix{display:flex;gap:16px;align-items:flex-start;flex-wrap:wrap;margin-top:12px}#qr-pix{width:170px;height:170px;background:#fff;border-radius:12px;padding:6px;flex:none}#qr-pix svg{width:100%;height:100%;display:block}
.pix > div:last-child{flex:1;min-width:220px}pre{white-space:pre-wrap;word-break:break-all;font:12.5px/1.45 ui-monospace,Consolas,monospace;background:var(--cod);border-radius:10px;padding:10px;margin-top:8px}
