#toast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%) translateY(20px);opacity:0;background:#18181b;color:#fff;padding:12px 16px;border-radius:12px;transition:.25s;z-index:9}#toast.on{opacity:1;transform:translateX(-50%) translateY(0)}
@media (max-width:720px){.pacs{grid-template-columns:1fr}.duas{grid-template-columns:1fr}.crono li{grid-template-columns:1fr;gap:2px}}
@media print{body{background:#fff;color:#000}header{background:#fff;color:#000;border-bottom:3px solid ${C}}.bts,#form-aceite,#imprimir,.no-print,#toast{display:none!important}.card{break-inside:avoid;border-color:#ccc}.pac{background:#fff}}
</style></head><body>
