<p>${ac ? '✅ Aceita' : vencida ? '⌛ Vencida' : `Válida até ${dataCurta(pr.validade_ate)}`}${pr.prazo_dias ? ` · prazo de ${pr.prazo_dias} dias` : ''}</p></div></header>
<main>
<section class="card"><h2>🔎 O que entendemos</h2><p>${esc(T.diagnostico)}</p>${T.objetivo ? `<p style="margin-top:8px"><b>Objetivo:</b> ${esc(T.objetivo)}</p>` : ''}</section>
${T.solucao ? `<section class="card"><h2>💡 A solução</h2><p>${esc(T.solucao)}</p></section>` : ''}
${T.escopo.length ? `<section class="card"><h2>📦 O que está incluído</h2><ul class="lista">${T.escopo.map(x => `<li>✔️ ${esc(x)}</li>`).join('')}</ul></section>` : ''}
${T.cronograma.length ? `<section class="card"><h2>🗓️ Cronograma</h2><ul class="crono">${T.cronograma.map(x => `<li><b>${esc(x.prazo)}</b><span>${esc(x.etapa)}</span></li>`).join('')}</ul></section>` : ''}
<section class="card"><h2>💰 ${pr.pacotes.length > 1 ? 'Escolha o pacote' : 'Investimento'}</h2><div class="pacs">${pacotesHtml}</div>
  <p class="sub" style="margin-top:12px">${pr.sinal_pct > 0 ? `Sinal de ${pr.sinal_pct}% no aceite${pr.prestador.pix ? ', pelo Pix' : ''}.` : ''} ${pr.pagamento ? esc(pr.pagamento) : ''}</p></section>
${T.garantias.length ? `<section class="card"><h2>🛡️ Garantia</h2><ul class="lista">${T.garantias.map(x => `<li>${esc(x)}</li>`).join('')}</ul></section>` : ''}
${T.faq.length ? `<section class="card"><h2>❓ Perguntas frequentes</h2>${T.faq.map(f => `<details><summary>${esc(f.p)}</summary><p>${esc(f.r)}</p></details>`).join('')}</section>` : ''}
${T.proximos_passos.length ? `<section class="card"><h2>👣 Próximos passos</h2><ol style="padding-left:20px;display:grid;gap:4px">${T.proximos_passos.map(x => `<li>${esc(x)}</li>`).join('')}</ol></section>` : ''}
${aceiteHtml}
<div class="rodape"><span>${esc(pr.prestador.nome)}${pr.prestador.empresa ? ' · ' + esc(pr.prestador.empresa) : ''}${pr.prestador.email ? ' · ' + esc(pr.prestador.email) : ''}</span>
<span class="bts no-print">${wa ? `<a class="bt" href="${esc(wa)}" target="_blank" rel="noopener">💬 Tirar dúvida no WhatsApp</a>` : ''}<button class="bt" id="imprimir">🖨️ Imprimir / PDF</button></span></div>
</main><div id="toast" role="status" aria-live="polite"></div>
<script>(${cliente.toString()})(${JSON.stringify({ id: pr.id, recomendado: (ac && ac.pacote) || pr.recomendado, aceita: !!ac, pix: pix && pix.texto,
  pacotes: pr.pacotes.map(p => ({ k: p.k, nome: p.nome, preco_txt: ppBRL(p.preco) })) }).replace(/</g, '\\u003c')});</script>
</body></html>`;
return [{ json: { codigo: 200, html, contar: q.p !== '1' && !robo, chaveP: pr.chaveP, cliente: pr.cliente.empresa || pr.cliente.nome, titulo: T.titulo } }];

// O cliente abriu a proposta: avisa o prestador na 1ª, 2ª, 3ª, 5ª, 10ª e 20ª vez (mais que isso vira chateação).
const v = $('📄 Desenha a proposta').first().json;
const n = Number(Object.values($('🧮 Conta a visita').first().json || {})[0]) || 1;
const aviso = [1, 2, 3, 5, 10, 20].includes(n) ? { titulo: `👀 ${v.cliente} abriu a proposta${n > 1 ? ` (${n}ª vez)` : ''}`.slice(0, 80),
  texto: `"${v.titulo}". ${n >= 3 ? 'Está pensando: bom momento para mandar uma mensagem.' : 'Ela acabou de ser aberta.'}`.slice(0, 160), url: 'painel', tag: 'visita' } : null;
return [{ json: { aviso, visitas: n } }];

// Web Push: a mensagem vai criptografada só para aquele celular (RFC 8291) e assinada com a chave do programa (VAPID, RFC 8292).
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
function criptografa(sub, texto) {
  const cr = require('crypto');
  const uaPublica = unb(sub.keys.p256dh), segredo = unb(sub.keys.auth);
  const ecdh = cr.createECDH('prime256v1'); ecdh.generateKeys();
  const asPublica = ecdh.getPublicKey();
  const compartilhado = ecdh.computeSecret(uaPublica);
  const sal = cr.randomBytes(16);
  const info = Buffer.concat([Buffer.from('WebPush: info\0'), uaPublica, asPublica]);
  const ikm = Buffer.from(cr.hkdfSync('sha256', compartilhado, segredo, info, 32));
  const cek = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
  const nonce = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: nonce\0'), 12));
  const c = cr.createCipheriv('aes-128-gcm', cek, nonce);
  const cifrado = Buffer.concat([c.update(Buffer.concat([Buffer.from(texto, 'utf8'), Buffer.from([2])])), c.final(), c.getAuthTag()]);
  const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
  return Buffer.concat([sal, rs, Buffer.from([asPublica.length]), asPublica, cifrado]);
}
function vapid(prog, endpoint) {
  const cr = require('crypto');
  const cab = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  // "aud" = endereço do serviço de avisos (Google, Apple ou Mozilla); o Code node não tem URL(), então recorto o texto
  const corpo = b64u(JSON.stringify({ aud: (String(endpoint).match(/^https:\/\/[^/]+/) || [''])[0], exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: 'https://webhookn8n6.inovareinteligenciaartificial.com' }));
  const assinatura = cr.sign('sha256', Buffer.from(cab + '.' + corpo), { key: cr.createPrivateKey({ key: prog.vapid.privada, format: 'jwk' }), dsaEncoding: 'ieee-p1363' });
  return `vapid t=${cab}.${corpo}.${b64u(assinatura)}, k=${prog.vapid.publica}`;
}
// {nome} = primeiro nome do cliente · {faltam} = carimbos que faltam para o prêmio
const pers = (t, c, prog) => String(t || '').replace(/\{nome\}/g, String(c.nome || '').split(' ')[0]).replace(/\{faltam\}/g, Math.max(1, prog.meta - c.carimbos));

// Avisa no celular do prestador (todos os aparelhos em que ele ligou os avisos). Inscrição com chave quebrada é pulada.
const subs = $('🗂️ Lê os celulares do prestador (visita)').first().json || {};
let prest = null;
try { prest = JSON.parse($('📖 Lê o prestador (visita)').first().json.prestador || 'null'); } catch (e) {}
const m = $('🧩 Monta o aviso da visita').first().json.aviso;
if (!prest || !prest.vapid || !m) return [];
const pref = 'ppush:' + prest.chaveP + ':', saida = [];
Object.entries(subs).filter(([k]) => k.startsWith(pref)).forEach(([k, v]) => {
  let s = null;
  try { s = JSON.parse(v); } catch (e) {}
  if (!s || !s.endpoint) return;
  try {
    saida.push({ json: { chave: k, endpoint: s.endpoint, autorizacao: vapid(prest, s.endpoint) },
      binary: { corpo: { data: criptografa(s, JSON.stringify(m)).toString('base64'), mimeType: 'application/octet-stream', fileName: 'aviso.bin' } } });
  } catch (e) {}
});
return saida;

// Lê o pedido da página da proposta (aceitar ou "já paguei") e guarda IP e navegador para o registro do aceite.
const ent = $('🔔 Pedido da proposta (POST)').first().json;
let b = ent.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const h = ent.headers || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f<>{}]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const id = /^[a-z0-9-]{4,60}$/.test(String(b.id || '')) ? String(b.id) : '';
return [{ json: { acao: ['aceitar', 'paguei'].includes(b.acao) && id ? b.acao : 'invalida', id, pacote: /^k\d$/.test(String(b.pacote || '')) ? b.pacote : '',
  nome: limpa(b.nome, 80), documento: String(b.documento || '').replace(/\D/g, '').slice(0, 14), email: limpa(b.email, 80), aceite: b.aceite === true,
  ip: String(h['x-forwarded-for'] || h['x-real-ip'] || '').split(',')[0].trim().slice(0, 45), navegador: String(h['user-agent'] || '').slice(0, 200),
  k_proposta: 'pp:' + (id || '-'), k_aceite: 'ppa:' + (id || '-'), k_pagamento: 'ppg:' + (id || '-') } }];

// Pix copia e cola no padrão BR Code do Banco Central (EMV + CRC16), o mesmo do agente de vendas.
function ppPix(chave, nome, cidade, valor, txid) {
  const emv = (id, v) => { const s = String(v); return id + String(s.length).padStart(2, '0') + s; };
  const ascii = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 ]/g, '').toUpperCase();
  let p = emv('00', '01') + emv('26', emv('00', 'br.gov.bcb.pix') + emv('01', chave)) + emv('52', '0000') + emv('53', '986') + emv('54', valor.toFixed(2));
  p += emv('58', 'BR') + emv('59', ascii(nome).slice(0, 25) || 'RECEBEDOR') + emv('60', ascii(cidade).slice(0, 15) || 'BRASIL')
    + emv('62', emv('05', String(txid).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || '***')) + '6304';
  let c = 0xFFFF;
  for (let i = 0; i < p.length; i++) { c ^= p.charCodeAt(i) << 8; for (let j = 0; j < 8; j++) { c = (c & 0x8000) ? ((c << 1) ^ 0x1021) : (c << 1); c &= 0xFFFF; } }
  return p + c.toString(16).toUpperCase().padStart(4, '0');
}
const ppBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// Aceite (com registro de nome, data, hora, IP e navegador) e "já paguei". Cada um avisa o prestador no celular.
const P = $('🧩 Lê o pedido da proposta').first().json;
let pr = null, ac = null, pg = null;
try { pr = JSON.parse($('📖 Lê a proposta (API)').first().json.proposta || 'null'); } catch (e) {}
try { ac = JSON.parse($('📖 Lê o aceite (API)').first().json.aceite || 'null'); } catch (e) {}
try { pg = JSON.parse($('📖 Lê o pagamento (API)').first().json.pagamento || 'null'); } catch (e) {}
const agora = Date.now(), sets = [];
let aviso = null;
const sai = (codigo, corpo) => [{ json: { codigo, resposta: JSON.stringify(corpo), sets, aviso, chaveP: pr ? pr.chaveP : '' } }];
const erro = (msg, codigo = 400) => sai(codigo, { ok: false, erro: msg });
if (!pr) return erro('Proposta não encontrada.', 404);
