if (P.acao === 'aceitar') {
  if (ac) return sai(200, { ok: true, ja: true });
  if (agora > pr.validade_ate) return erro('Esta proposta venceu. Peça uma atualizada ao prestador.');
  const pac = pr.pacotes.find(p => p.k === P.pacote);
  if (!pac) return erro('Escolha um pacote.');
  if (P.nome.length < 5 || !/\S\s+\S/.test(P.nome)) return erro('Digite o nome completo de quem está aceitando.');
  if (!P.aceite) return erro('Marque que leu e aceita a proposta.');
  if (P.documento && ![11, 14].includes(P.documento.length)) return erro('CPF (11 números) ou CNPJ (14 números) incompleto.');
  if (P.email && !/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(P.email)) return erro('O e-mail parece errado.');
  const a = { pacote: pac.k, pacote_nome: pac.nome, valor: pac.preco, sinal: Math.round(pac.preco * pr.sinal_pct) / 100,
    nome: P.nome, documento: P.documento, email: P.email, ip: P.ip, navegador: P.navegador, quando: agora };
  sets.push({ chave: 'ppa:' + pr.id, valor: JSON.stringify(a), ttl: TTL });
  aviso = { titulo: `🎉 ${quem} aceitou!`.slice(0, 80), texto: `${pac.nome} · ${ppBRL(pac.preco)}${a.sinal ? ' · sinal de ' + ppBRL(a.sinal) : ''}`, url: 'painel', tag: 'aceite-' + pr.id };
  return sai(200, { ok: true, aceite: { pacote: pac.nome, valor: pac.preco, sinal: a.sinal } });
}

if (P.acao === 'paguei') {
  if (!ac) return erro('Aceite a proposta antes de informar o pagamento.');
  if (pg) return sai(200, { ok: true, ja: true });
  sets.push({ chave: 'ppg:' + pr.id, valor: JSON.stringify({ status: 'informado', quando: agora }), ttl: TTL });
  aviso = { titulo: `💸 ${quem} informou o pagamento`.slice(0, 80), texto: `Sinal de ${ppBRL(ac.sinal)} de "${pr.textos.titulo}". Confira no banco e confirme no painel.`.slice(0, 170), url: 'painel', tag: 'pago-' + pr.id };
  return sai(200, { ok: true });
}
return erro('Pedido inválido.');

// Web Push: a mensagem vai criptografada só para aquele celular (RFC 8291) e assinada com a chave do programa (VAPID, RFC 8292).
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
