// Pix copia e cola no padrão BR Code do Banco Central (EMV + CRC16), o mesmo do agente de vendas.
function ppPix(chave, nome, cidade, valor, txid) {
  const emv = (id, v) => { const s = String(v); return id + String(s.length).padStart(2, '0') + s; };
  const ascii = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 ]/g, '').toUpperCase();
  let p = emv('00', '01') + emv('26', emv('00', 'br.gov.bcb.pix') + emv('01', chave)) + emv('52', '0000') + emv('53', '986') + emv('54', valor.toFixed(2));
  p += emv('58', 'BR') + emv('59', ascii(nome).slice(0, 25) || 'RECEBEDOR') + emv('60', ascii(cidade).slice(0, 15) || 'BRASIL')
    + emv('62', emv('05', String(txid).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || '***')) + '6304';
  let c = 0xFFFF;
  for (let i = 0; i < p.length; i++) { c ^= p.charCodeAt(i) << 8; for (let j = 0; j < 8; j++) { c = (c & 0x8000) ? ((c << 1) ^ 0x1021) : (c << 1); c &= 0xFFFF; } }
  return p + c.toString(16).toUpperCase().padStart(4, '0');
}
const ppBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');

