const d = $('🔑 Confere a chave e decide (proposta)').first().json;
let rv = null, rd = null;
try { rv = parseJSON($('🤖 Revisora do follow-up').first().json.output); } catch (e) {}
try { rd = parseJSON($('🤖 Redatora de follow-up').first().json.output); } catch (e) {}
const a = rv && rv.mensagem ? rv : (rd && rd.mensagem ? rd : null);
if (!a) return [{ json: { resposta: JSON.stringify({ ok: false, erro: 'A IA não respondeu agora. Tente de novo.' }) } }];
const mensagem = String(a.mensagem).replace(/\[link\]/gi, d.link).slice(0, 700);
return [{ json: { resposta: JSON.stringify({ ok: true, mensagem, wa: d.whatsapp ? 'https://wa.me/' + d.whatsapp + '?text=' + encodeURIComponent(mensagem) : '',
  problemas: a === rv && Array.isArray(rv.problemas) ? rv.problemas.map(p => String(p).slice(0, 160)).slice(0, 4) : [] }) } }];

// Um item por proposta do prestador (índice ppx:<chave>:<id>). Sem nenhuma, 1 item vazio para a página mostrar o "comece aqui".
const chave = String(($('🔔 Abrir painel do prestador (GET)').first().json.params || {}).id || '');
const ids = Object.keys($('🗂️ Lê o índice do prestador').first().json || {}).filter(k => k.startsWith('ppx:' + chave + ':')).map(k => k.split(':')[2]);
return (ids.length ? ids : ['-']).map(id => ({ json: { id } }));

// Pix copia e cola no padrão BR Code do Banco Central (EMV + CRC16), o mesmo do agente de vendas.
function ppPix(chave, nome, cidade, valor, txid) {
  const emv = (id, v) => { const s = String(v); return id + String(s.length).padStart(2, '0') + s; };
  const ascii = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 ]/g, '').toUpperCase();
  let p = emv('00', '01') + emv('26', emv('00', 'br.gov.bcb.pix') + emv('01', chave)) + emv('52', '0000') + emv('53', '986') + emv('54', valor.toFixed(2));
  p += emv('58', 'BR') + emv('59', ascii(nome).slice(0, 25) || 'RECEBEDOR') + emv('60', ascii(cidade).slice(0, 15) || 'BRASIL')
    + emv('62', emv('05', String(txid).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || '***')) + '6304';
  let c = 0xFFFF;
  for (let i = 0; i < p.length; i++) { c ^= p.charCodeAt(i) << 8; for (let j = 0; j < 8; j++) { c = (c & 0x8000) ? ((c << 1) ^ 0x1021) : (c << 1); c &= 0xFFFF; } }
  return p + c.toString(16).toUpperCase().padStart(4, '0');
}
const ppBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// Painel do prestador: todas as propostas (enviada, vista, aceita, paga), visitas, registro do aceite, follow-up da IA e avisos no celular. "?json=1" devolve os dados.
const ent = $('🔔 Abrir painel do prestador (GET)').first().json;
const chave = String((ent.params || {}).id || ''), q = ent.query || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
let prest = null;
try { prest = JSON.parse($('📖 Lê o prestador (painel)').first().json.prestador || 'null'); } catch (e) {}
if (!prest || prest.chaveP !== chave) return [{ json: { codigo: 404, tipo: 'text/html; charset=UTF-8', html: `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel</title><meta name="robots" content="noindex"></head>
<body style="font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#f6f6f4;color:#222;text-align:center;padding:24px"><div><div style="font-size:56px">🔒</div><h1 style="font-size:22px">Painel não encontrado</h1><p style="color:#666">Use o link completo do painel que apareceu quando você criou a proposta.</p></div></body></html>` } }];
const agora = Date.now();
const base = String(ent.webhookUrl || '').split('/webhook/')[0] + '/webhook';
// os nomes dos nodes ficam escritos por extenso em $('...'): é assim que o montador acha e atualiza quando põe os emojis
const todos = no => no.all().map(x => x.json || {});
const props = todos($('📖 Lê a proposta (painel)')), aceites = todos($('📖 Lê o aceite (painel)')), pags = todos($('📖 Lê o pagamento (painel)')),
  vis = todos($('📖 Lê as visitas (painel)')), ults = todos($('📖 Lê a última visita (painel)'));
const js = s => { try { return JSON.parse(s || 'null'); } catch (e) { return null; } };
const linhas = $('🧩 Separa as propostas').all().map((it, i) => {
  const pr = js((props[i] || {}).proposta);
  if (!pr) return null;
  const ac = js((aceites[i] || {}).aceite), pg = js((pags[i] || {}).pagamento), n = Number((vis[i] || {}).visitas) || 0, ult = Number((ults[i] || {}).ultima) || 0;
  const status = pg && pg.status === 'confirmado' ? 'paga' : pg ? 'pagamento informado' : ac ? 'aceita' : agora > pr.validade_ate ? 'vencida' : n ? 'vista' : 'enviada';
  const precos = pr.pacotes.map(p => p.preco);
  return { id: pr.id, titulo: pr.textos.titulo, cliente: pr.cliente.empresa || pr.cliente.nome, contato: pr.cliente.nome, whatsapp: pr.cliente.whatsapp || '',
    de: Math.min(...precos), ate: Math.max(...precos), valor: ac ? ac.valor : 0, pacote: ac ? ac.pacote_nome : '', sinal: ac ? ac.sinal : 0,
    criado: pr.criado, validade: pr.validade_ate, visitas: n, ultima: ult, status, link: `${base}/proposta/${pr.id}/ver`,
    aceite: ac ? { nome: ac.nome, documento: ac.documento, email: ac.email, ip: ac.ip, navegador: ac.navegador, quando: ac.quando } : null };
}).filter(Boolean).sort((a, b) => b.criado - a.criado);
if (q.json === '1') return [{ json: { codigo: 200, tipo: 'application/json; charset=UTF-8', html: JSON.stringify({ ok: true, propostas: linhas }) } }];

const soma = f => linhas.reduce((a, l) => a + (Number(f(l)) || 0), 0);
const aceitas = linhas.filter(l => l.valor > 0);
const kpis = [['📤', linhas.length, 'propostas', `${linhas.filter(l => l.visitas > 0).length} abertas pelo cliente`],
  ['✅', aceitas.length, 'aceitas', linhas.length ? Math.round(aceitas.length / linhas.length * 100) + '% de aceite' : '—'],
  ['💰', ppBRL(soma(l => l.valor)), 'fechado', `${linhas.filter(l => l.status === 'paga').length} com sinal confirmado`],
  ['🕒', linhas.filter(l => ['enviada', 'vista'].includes(l.status)).length, 'esperando resposta', `${linhas.filter(l => l.status === 'pagamento informado').length} pagamento(s) para conferir`]];

function painel(D) {
  var el = function (s) { return document.querySelector(s); };
  var esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
  var brl = function (n) { return 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.'); };
  var data = function (ms) { return ms ? new Date(ms).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—'; };
  var ST = { enviada: '📤 enviada', vista: '👀 vista', aceita: '✅ aceita', 'pagamento informado': '💸 pagamento informado', paga: '💰 paga', vencida: '⌛ vencida' };
  function toast(t) { var x = el('#toast'); x.textContent = t; x.classList.add('on'); clearTimeout(x._t); x._t = setTimeout(function () { x.classList.remove('on'); }, 4500); }
  function api(d) {
    return fetch('/webhook/proposta-dono', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(Object.assign({ chave: D.chave }, d)) })
      .then(function (r) { return r.json(); }).catch(function () { return { ok: false, erro: 'Sem conexão.' }; });
  }
  var ordem = { campo: 'criado', dir: -1 }, busca = '';
  var COLS = [['titulo', 'Proposta'], ['ate', 'Valor'], ['status', 'Situação'], ['visitas', 'Visitas'], ['criado', 'Enviada'], ['validade', 'Validade']];
  function filtradas() {
    var b = busca.toLowerCase();
    return D.linhas.filter(function (l) { return !b || (l.titulo + ' ' + l.cliente + ' ' + l.status).toLowerCase().indexOf(b) > -1; })
      .sort(function (a, c) { var x = a[ordem.campo], y = c[ordem.campo]; return (x > y ? 1 : x < y ? -1 : 0) * ordem.dir; });
  }
  function tabela() {
    var ls = filtradas();
    el('#thead').innerHTML = '<tr>' + COLS.map(function (c) { return '<th><button data-campo="' + c[0] + '">' + c[1] + (ordem.campo === c[0] ? (ordem.dir > 0 ? ' ▲' : ' ▼') : '') + '</button></th>'; }).join('') + '<th>Ações</th></tr>';
    el('#tbody').innerHTML = ls.map(function (l) {
      var envio = l.whatsapp ? 'https://wa.me/' + l.whatsapp + '?text=' + encodeURIComponent('Olá, ' + l.contato.split(' ')[0] + '! Segue a proposta "' + l.titulo + '": ' + l.link) : '';
      return '<tr><td><a href="' + l.link + '?p=1" target="_blank" rel="noopener"><b>' + esc(l.titulo) + '</b></a><small>' + esc(l.cliente) + '</small></td>'
        + '<td>' + (l.valor ? '<b>' + brl(l.valor) + '</b><small>' + esc(l.pacote) + '</small>' : (l.de === l.ate ? brl(l.de) : brl(l.de) + ' a ' + brl(l.ate))) + '</td>'
        + '<td><span class="chip ' + l.status.replace(/\s/g, '-') + '">' + ST[l.status] + '</span></td>'
        + '<td>' + l.visitas + (l.ultima ? '<small>última ' + data(l.ultima) + '</small>' : '') + '</td><td>' + data(l.criado) + '</td><td>' + new Date(l.validade).toLocaleDateString('pt-BR') + '</td>'
        + '<td class="acoes"><button class="bt" data-copiar="' + l.link + '">📋</button>' + (envio ? '<a class="bt" href="' + envio + '" target="_blank" rel="noopener">💬 Enviar</a>' : '')
        + '<button class="bt" data-follow="' + l.id + '">✨ Follow-up</button>'
        + (l.status === 'aceita' || l.status === 'pagamento informado' ? '<button class="bt pri" data-confirmar="' + l.id + '">💰 Confirmar sinal</button>' : '')
        + (l.aceite ? '<details><summary>Registro do aceite</summary><p>' + esc(l.aceite.nome) + (l.aceite.documento ? ' · doc ' + esc(l.aceite.documento) : '') + (l.aceite.email ? ' · ' + esc(l.aceite.email) : '')
          + '<br>' + new Date(l.aceite.quando).toLocaleString('pt-BR') + ' · IP ' + esc(l.aceite.ip || '?') + '<br><small>' + esc(l.aceite.navegador) + '</small></p></details>' : '') + '</td></tr>';
    }).join('') || '<tr><td colspan="7" class="vazio">Nenhuma proposta ainda. Toque em "Nova proposta".</td></tr>';
    el('#qtd').textContent = ls.length + ' de ' + D.linhas.length + ' propostas';
  }
  el('#thead').addEventListener('click', function (e) { var b = e.target.closest('[data-campo]'); if (!b) return; ordem = { campo: b.dataset.campo, dir: ordem.campo === b.dataset.campo ? -ordem.dir : -1 }; tabela(); });
  el('#busca').addEventListener('input', function () { busca = this.value; tabela(); });
  el('#csv').addEventListener('click', function () {
    var qv = function (v) { v = String(v == null ? '' : v); return /[",;\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; };
    var corpo = ['proposta;cliente;valor_aceito;pacote;de;ate;situacao;visitas;enviada;validade;link'].concat(filtradas().map(function (l) {
      return [l.titulo, l.cliente, l.valor, l.pacote, l.de, l.ate, l.status, l.visitas, new Date(l.criado).toLocaleDateString('pt-BR'), new Date(l.validade).toLocaleDateString('pt-BR'), l.link].map(qv).join(';'); }));
    var a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['\ufeff' + corpo.join('\n')], { type: 'text/csv;charset=utf-8' })); a.download = 'propostas.csv'; a.click();
  });
  tabela();
  document.addEventListener('click', function (e) {
    var c = e.target.closest('[data-copiar]'); if (c) { navigator.clipboard.writeText(c.dataset.copiar).then(function () { toast('Link copiado'); }); return; }
    var f = e.target.closest('[data-follow]');
    if (f) {
      f.disabled = true; f.textContent = '⏳';
      api({ acao: 'followup', id: f.dataset.follow }).then(function (r) {
        f.disabled = false; f.textContent = '✨ Follow-up';
        if (!r.ok) { toast('⚠️ ' + r.erro); return; }
        el('#fu').hidden = false; el('#fu-txt').textContent = r.mensagem; el('#fu-wa').href = r.wa; el('#fu-wa').hidden = !r.wa;
        el('#fu-rev').textContent = r.problemas && r.problemas.length ? '🔍 A revisora ajustou: ' + r.problemas.join(' · ') : '';
        el('#fu').scrollIntoView({ behavior: 'smooth' });
      });
      return;
    }
    var k = e.target.closest('[data-confirmar]');
    if (k && confirm('Confirmar que o sinal caiu na sua conta?')) {
      k.disabled = true;
      api({ acao: 'confirmar', id: k.dataset.confirmar }).then(function (r) { if (!r.ok) { k.disabled = false; toast('⚠️ ' + r.erro); return; } toast('💰 Pagamento confirmado'); setTimeout(function () { location.reload(); }, 900); });
    }
  });
  el('#fu-copiar').addEventListener('click', function () { var b = this; navigator.clipboard.writeText(el('#fu-txt').textContent).then(function () { b.textContent = '✅ Copiado'; }); });
  // avisos no celular do prestador (abriu, aceitou, pagou)
  function chaveBytes(b64) { var pd = '='.repeat((4 - b64.length % 4) % 4), s = atob((b64 + pd).replace(/-/g, '+').replace(/_/g, '/')), a = new Uint8Array(s.length); for (var i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; }
  var bt = el('#bt-avisos');
  if (!('serviceWorker' in navigator) || !('PushManager' in window)) bt.hidden = true;
  if ('Notification' in window && Notification.permission === 'granted' && localStorage.getItem('pp-avisos-' + D.chave)) { bt.textContent = '✅ Avisos ligados neste aparelho'; bt.disabled = true; }
  bt.addEventListener('click', function () {
    bt.disabled = true; bt.textContent = '⏳ Ligando…';
    navigator.serviceWorker.register('avisos').then(function () { return Notification.requestPermission(); }).then(function (perm) {
      if (perm !== 'granted') throw new Error('sem permissão');
      return navigator.serviceWorker.ready.then(function (reg) { return reg.pushManager.getSubscription().then(function (s) { return s || reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: chaveBytes(D.vapid) }); }); });
    }).then(function (s) { return api({ acao: 'inscrever', sub: s.toJSON() }); }).then(function (r) {
      if (!r.ok) throw new Error(r.erro);
      try { localStorage.setItem('pp-avisos-' + D.chave, '1'); } catch (e) {}
      bt.textContent = '✅ Avisos ligados neste aparelho'; toast('🔔 Você vai saber quando o cliente abrir, aceitar ou pagar.');
    }).catch(function () { bt.disabled = false; bt.textContent = '🔔 Avisar no celular'; toast('Não deu para ligar os avisos neste aparelho.'); });
  });
}

