// Service worker do painel do prestador: só mostra os avisos (abriu, aceitou, pagou) e abre o painel ao tocar.
const id = String(($('🔔 Pedido do motor da proposta (GET)').first().json.params || {}).id || '').replace(/[^a-f0-9]/g, '');
function motor() {
  self.addEventListener('install', function () { self.skipWaiting(); });
  self.addEventListener('activate', function (e) { e.waitUntil(self.clients.claim()); });
  self.addEventListener('push', function (e) {
    var d = {};
    try { d = e.data ? e.data.json() : {}; } catch (x) { d = { texto: e.data ? e.data.text() : '' }; }
    e.waitUntil(self.registration.showNotification(d.titulo || 'Novidade nas suas propostas', { body: d.texto || '', tag: d.tag || 'proposta', data: { url: d.url || 'painel' } }));
  });
  self.addEventListener('notificationclick', function (e) {
    e.notification.close();
    var alvo = new URL(e.notification.data && e.notification.data.url || 'painel', self.registration.scope).href;
    e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (ws) {
      for (var i = 0; i < ws.length; i++) { if (ws[i].url.indexOf(self.registration.scope) === 0 && 'focus' in ws[i]) { ws[i].navigate(alvo); return ws[i].focus(); } }
      return self.clients.openWindow(alvo);
    }));
  });
}
return [{ json: { js: id.length === 16 ? `(${motor.toString()})();` : '/* painel inválido */' } }];

