// confere cada passo; se algo não bateu, o node fica vermelho dizendo o quê
const l = $('👉 Guarda os links').first().json, ac = $('🌐 Cliente aceita o Completo').first().json, pg = $('🌐 Cliente avisa que pagou').first().json;
const conf = $('🌐 Prestador confirma o sinal').first().json, pagina = String($('🌐 Página com o Pix (prévia)').first().json.data || '');
let painel = {};
try { painel = JSON.parse($input.first().json.data || '{}'); } catch (e) {}
const p = (painel.propostas || []).find(x => x.id === l.id) || {};
const falhas = [];
if (!String($('🌐 Cliente abre a proposta').first().json.data || '').includes('Clínica Sorriso')) falhas.push('a página do cliente não abriu');
if (!ac.ok || ac.aceite.valor !== 3400 || ac.aceite.sinal !== 1700) falhas.push('aceite errado: ' + JSON.stringify(ac).slice(0, 200));
if (!pg.ok) falhas.push('"já paguei" falhou: ' + JSON.stringify(pg));
if (!conf.ok) falhas.push('o prestador não confirmou: ' + JSON.stringify(conf));
const pix = (pagina.match(/<pre id="pix-txt">([^<]+)<\/pre>/) || [0, ''])[1];   // o código do Pix tem espaços (nome e cidade do recebedor)
if (!pix.includes('br.gov.bcb.pix') || !pix.includes('54071700.00')) falhas.push('Pix do sinal não apareceu certo na página: ' + pix.slice(0, 120));
if (p.visitas !== 2) falhas.push('o painel deveria mostrar 2 visitas (a prévia não conta): ' + p.visitas);
if (p.status !== 'paga') falhas.push('status no painel deveria ser "paga": ' + p.status);
if (!p.aceite || !p.aceite.ip) falhas.push('o registro do aceite (com IP) não está no painel');
if (falhas.length) throw new Error(falhas.join(' | '));
return [{ json: { '✅': 'Proposta criada, aberta 2 vezes, Completo aceito (R$ 3.400), sinal de R$ 1.700 no Pix informado e confirmado', '📄 proposta (cliente)': l.link,
  '📊 painel do prestador': l.painel_url, '💸 Pix copia e cola': pix, '✍️ aceite': `${p.aceite.nome} · IP ${p.aceite.ip}`, '👀 visitas': p.visitas, '📌 situação': p.status } }];
